def _check_single_task_file_count(task, fps: list) -> list[str]:
    """Check that a task has exactly 1 file path."""
    if len(fps) != 1:
        return [f"task {getattr(task, 'id', '?')} lists {len(fps)} files (exactly 1 required)"]
    return []


def _check_file_collisions(fps: list[str], seen: set[str]) -> list[str]:
    """Check for duplicate file paths and track seen files."""
    violations: list[str] = []
    for fp in fps:
        if fp in seen:
            violations.append(f"file collision: {fp} in multiple tasks")
        seen.add(fp)
    return violations"}
